from pathlib import Path
import base64,json
import numpy as np
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
COLORS={'Persistence':'#78838b','Seasonal':'#d18b21','Ridge':'#2469ae','HGB':'#39834f','LSTM':'#a04d96'}
def render(out):
    out=Path(out);cfg=json.loads((out/'config_frozen.json').read_text());models=list(COLORS);met=pd.read_csv(out/'metrics.csv');cov=pd.read_csv(out/'coverage.csv');d=pd.read_csv(out/'asof_minus_revised.csv');elig=pd.read_csv(out/'eligibility.csv');pred=pd.read_csv(out/'scores.csv');figs=out/'figures';figs.mkdir(exist_ok=True)
    plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False});seasons=sorted(elig.fold.unique())
    counts=elig.groupby(['fold','stage']).included.agg(['sum','count']).reset_index();counts['eligible_fraction']=counts['sum']/counts['count'];counts.to_csv(out/'availability_summary.csv',index=False)
    fig,ax=plt.subplots(figsize=(11,4),layout='constrained')
    for stage in ['train','validation','refit','test']:
        g=counts[counts.stage==stage].set_index('fold').loc[seasons];ax.plot(seasons,g.eligible_fraction,'o-',label=stage)
    ax.set(ylim=(0,1.05),ylabel='Eligible fraction of original candidate windows',title='Availability restriction applied identically to both new regimes');ax.legend(ncol=4);fig.savefig(figs/'availability.png',dpi=150);plt.close(fig)
    fig,axes=plt.subplots(1,3,figsize=(15,5),layout='constrained');x=np.arange(5)
    for ax,col,title in zip(axes,['point_macro_mae','point_rmse','macro_wis'],['Point MAE','Point RMSE','WIS']):
        for i,regime in enumerate(['AsOf','MatchedRevised','OriginalFrozen']):
            g=met[(met.scope=='overall')&(met.regime==regime)].set_index('model').loc[models];ax.bar(x+(i-1)*.24,g[col],width=.24,label=regime)
        ax.set_xticks(x,models,rotation=25);ax.set(title=title,ylabel='Percentage points; lower is better')
    axes[0].legend(fontsize=8);fig.savefig(figs/'overall_comparison.png',dpi=150);plt.close(fig)
    fig,axes=plt.subplots(2,3,figsize=(14,8),layout='constrained')
    for model,ax in zip(models,axes.flat):
        for regime,style in [('AsOf','-'),('MatchedRevised','--')]:
            g=met[(met.scope=='season')&(met.regime==regime)&(met.model==model)].set_index('group').loc[seasons];ax.plot(seasons,g.macro_wis,'o'+style,label=regime,color=COLORS[model])
        ax.set(title=model,ylabel='Macro-WIS (pp)');ax.tick_params(axis='x',rotation=40);ax.legend(fontsize=8)
    axes.flat[-1].axis('off');axes.flat[-1].text(.05,.8,'Same sample IDs, masks and model rules.\nAsOf: archive-available values.\nMatchedRevised: hindsight values.\nNo significance test is implied.',transform=axes.flat[-1].transAxes,va='top');fig.savefig(figs/'season_wis.png',dpi=150);plt.close(fig)
    fig,ax=plt.subplots(figsize=(10,5),layout='constrained')
    for i,regime in enumerate(['AsOf','MatchedRevised']):
        g=cov[(cov.scope=='overall')&(cov.regime==regime)&(cov.nominal_coverage==.95)].set_index('model').loc[models];ax.bar(x+(i-.5)*.32,g.coverage,width=.32,label=regime)
    ax.axhline(.95,color='black',ls='--',label='Nominal 95%');ax.set_xticks(x,models);ax.set(ylim=(0,1),ylabel='Observed 95% interval coverage',title='Residual distributions fitted only before each outer season');ax.legend();fig.savefig(figs/'coverage95.png',dpi=150);plt.close(fig)
    fig,ax=plt.subplots(figsize=(10,5),layout='constrained')
    for model in models:
        g=d[(d.scope=='season')&(d.model==model)].set_index('group').loc[seasons];ax.plot(seasons,g.delta_macro_wis,'o-',color=COLORS[model],label=model)
    ax.axhline(0,color='black',ls='--');ax.set(ylabel='AsOf minus MatchedRevised WIS (pp)',title='Vintage effect on the full selected/refit pipeline');ax.legend(ncol=5,fontsize=9);fig.savefig(figs/'wis_difference.png',dpi=150);plt.close(fig)
    revisions=[]
    for fold in seasons:
        a=pd.read_csv(out/'folds'/fold/'AsOf/test_windows.csv.gz');b=pd.read_csv(out/'folds'/fold/'MatchedRevised/test_windows.csv.gz')
        assert a.sample_id.tolist()==b.sample_id.tolist()
        for j in range(12):
            delta=a[f'lag_{j}']-b[f'lag_{j}'];revisions.append(dict(fold=fold,lag_index=j,n=len(a),mean_signed_revision=float(delta.mean()),mean_absolute_revision=float(abs(delta).mean()),max_absolute_revision=float(abs(delta).max())))
    rev=pd.DataFrame(revisions);rev.to_csv(out/'feature_revision_summary.csv',index=False)
    fig,ax=plt.subplots(figsize=(10,5),layout='constrained')
    for fold,g in rev.groupby('fold'):ax.plot(g.lag_index,g.mean_absolute_revision,'o-',label=fold)
    ax.set(xlabel='Input position (0 oldest; 11 origin week)',ylabel='Mean absolute vintage vs revised difference (pp)',title='Predictor revisions on the matched outer-test windows');ax.legend(fontsize=8,ncol=3);fig.savefig(figs/'predictor_revisions.png',dpi=150);plt.close(fig)
    def table(g):return g.to_html(index=False,border=0,float_format=lambda x:f'{x:.5f}')
    def img(name,cap):return f'<figure><img src="data:image/png;base64,{base64.b64encode((figs/name).read_bytes()).decode()}" alt="{cap}"><figcaption>{cap}</figcaption></figure>'
    overall=met[met.scope=='overall'];availability_dates=pred[(pred.regime=='AsOf')&(pred.model=='Ridge')].groupby('target_season').agg(n_samples=('sample_id','size'),first_origin=('origin_date','min'),last_origin=('origin_date','max'),first_target=('target_date','min'),last_target=('target_date','max')).reset_index();availability_dates.to_csv(out/'test_date_ranges.csv',index=False);a=overall[overall.regime=='AsOf'];best=a.loc[a.macro_wis.idxmin()];n=int(a.n.iloc[0]);cols=['regime','model','n','point_macro_mae','point_rmse','point_bias','macro_wis','median_mae','median_rmse'];choices=pd.read_csv(out/'model_selection_summary.csv')
    body=f'''<!doctype html><html lang="en"><meta charset="utf-8"><title>ILI v0.5 historical vintage comparison</title><style>body{{max-width:1250px;margin:35px auto;padding:0 25px;font:16px/1.65 system-ui;color:#20303a}}h1{{line-height:1.2}}h2{{margin-top:35px}}table{{display:block;overflow-x:auto;border-collapse:collapse;font-size:13px}}td,th{{padding:7px 10px;border-bottom:1px solid #ddd;text-align:right}}th{{background:#edf3f8}}img{{max-width:100%;height:auto}}figure{{margin:24px 0}}figcaption{{color:#52616d}}.note{{padding:18px;background:#edf4f9}}</style>
<h1>ILI Forecasts Using Historical Delphi Vintages</h1><p class="note">Release-date-constrained archive replay; six outer seasons and ten HHS regions. Issue at origin week-end +7 days, target at origin +14 days: a seven-day calendar lead from scheduled issuance. This preserves the old two-observation-week target, not a two-week-ahead release-time horizon.</p>
<h2>中文结论</h2><p>本轮实际下载 212,710 条历史版本记录，并在相同样本、训练窗口和模型规则下重新拟合 AsOf 与 MatchedRevised 两组模型。每模型最终有 {n} 个可评价样本，占原 3,010 个的 {100*n/3010:.1f}%。不满足档案可用性或季节基线参考条件的日期被两组共同排除，不能把结果解释为原全部日期的实时表现。尤其 2013–14 季只覆盖目标日期 2014-01-04 至 2014-05-17 的 20 周，不能代表该季全年。</p><p>AsOf 组最低 WIS 是 {best.model}，数值 {best.macro_wis:.5f}。下面直接列出 AsOf−MatchedRevised 的差值：正数表示使用当时版本后误差增加，负数表示减少。差异涵盖输入、训练标签、标准化、模型选择和残差分布共同改变的影响；不等同于只替换测试输入的单独效应，也不证明修订总会让结果变好。</p><p>早年缺失的夏季档案和延迟发布尤其重要。我们按 release_date 过滤，再选择当时最新版本；没有用后来修订值填补缺口。日期字段只有天级精度，因此这是基于可获得档案的实时信息模拟，不能保证复原每个历史时刻的全部发布过程。</p>
<h2>Matched overall comparison</h2>{table(overall[cols])}{img('overall_comparison.png','Only AsOf versus MatchedRevised is the controlled pipeline comparison. OriginalFrozen is historical context on the same outer sample IDs.')}
{table(d[d.scope=='overall'])}
<p>在这组匹配样本上，AsOf 和 MatchedRevised 的最低总体 WIS 都来自 Ridge。因此，不能把它与上一阶段全样本 HGB 领先的差别全部归因于 vintage：评价日期、训练可用性掩码和残差估计样本也改变了。</p><h2>Availability and exclusions</h2>{img('availability.png','Candidates originate from the previous rolling design. Both regimes use identical complete ten-region origin groups.')}{table(counts)}{table(availability_dates)}
<details><summary>Exclusion reasons</summary>{table(elig[~elig.included].groupby(['fold','stage','reason']).size().rename('n_samples').reset_index())}</details>
<p>Both origin and target remain inside their original stage/season. All twelve input observation weeks must exist in the archive by each issuance date. A value released long after its observation week is unavailable earlier, even when its issue label appears historical. No future revisions, interpolation or final-snapshot filling are used in AsOf. Seasonal predictions require historical same target-week observations, with only the original week53 fallback.</p>
<h2>Training, selection and residual distributions</h2><p>Selection weights and scalers use the snapshot at the first scheduled issuance of the preceding validation season. Validation inputs use their own issuance-date vintages; validation labels are the versions known at the next outer season's first scheduled issuance. At that outer cutoff, choose Ridge alpha and LSTM epoch, refit on available pre-test history, and estimate residual quantiles. These fitted objects remain fixed throughout the outer season. Historical training inputs may use revisions already known at fitting time. No outer targets enter model fitting, selection or residual estimation.</p><p>The same seven Ridge penalties, fixed HGB configuration, small LSTM architecture, 60-epoch maximum, early-stopping rule and seed2026 are reused. MatchedRevised uses exactly the same training/window/scaler-observation masks but substitutes values from the frozen 2026-10-20 snapshot. Its separate parameter choices reflect the full pipeline response to revisions; it is a hindsight comparator, not an available real-time model.</p>
{table(choices)}
<p>Each regime has 23 residual-based quantiles: empirical quantiles of preceding-validation outcome minus prediction, added to current point forecasts and clipped to [0,100]. AsOf residual labels use only versions available at the outer fit cutoff. Selection reuse and transfer from selection models to refit models prevent a guarantee of independent calibration or nominal coverage. WIS uses the unchanged v0.4 scoring formula; lower scores balance narrower intervals against misses. Point metrics refer to original model predictions; median metrics refer to residual-adjusted probability medians.</p>
<h2>Seasonal comparisons and revisions</h2>{img('season_wis.png','Season-specific WIS on the same eligible windows for both regimes.')}{img('wis_difference.png','No confidence interval or significance claim is attached. Earlier bootstrap indices are not reused because eligibility exclusions can create gaps.')}{img('predictor_revisions.png','Differences between historical available values and the frozen revised reference in each of the twelve input positions.')}
<h2>Interval coverage</h2>{img('coverage95.png','Coverage should be interpreted jointly with WIS and width; higher coverage alone is not optimal.')}{table(cov[(cov.scope=='overall')&cov.nominal_coverage.isin([.5,.8,.95])])}
<details><summary>All seasonal and regional metrics</summary>{table(met[met.scope!='overall'])}</details>
<details><summary>Seasonal 95% coverage</summary>{table(cov[(cov.scope=='season')&(cov.nominal_coverage==.95)])}</details>
<h2>Limitations and what remains preserved</h2><ul><li>Evaluation uses the same frozen revised outcomes for all methods. These are a reference snapshot, not an immutable biological ground truth.</li><li>Archive gaps restrict the evaluation population. Exclusions are based on availability before scoring, not model performance; nevertheless conditional sample selection limits generalization.</li><li>Release dates proxy archive availability at daily resolution. Intraday timing, unpublished historical versions and historical service outages cannot be reconstructed. Missing issue snapshots are not evidence that all observations were unavailable; latest prior released records remain usable.</li><li>The full project and point rankings were already viewed before this stage. This is exploratory retrospective backtesting, not preregistered unseen confirmation.</li><li>No new significance tests are offered. Shared training, regional and temporal dependence remain; previous consecutive-week bootstrap draws are unsuitable for this potentially gapped subset.</li><li>OriginalFrozen reuses v0.2/v0.4 models trained on a different historical sample set; compare it as context, not as an isolated vintage effect.</li><li>All prior v0.1–v0.4 artifacts and archives are retained byte-identically. New model fits live only under this phase's directory.</li></ul>
<h2>Sources, reproducibility and AI use</h2><p>Official <a href="https://cmu-delphi.github.io/delphi-epidata/api/fluview.html">Delphi FluView vintage API</a> supplies release_date, issue and observation week. <a href="https://cmu-delphi.github.io/delphi-epidata/api/v5-signals/fluview_ilinet.html">V5 source documentation</a> explains the weekly source and report-time interpretation. Queries follow the <a href="https://cmu-delphi.github.io/delphi-epidata/api/api_keys.html">documented anonymous-access limits</a>. Data are CDC ILINet via Delphi, publicly accessible US Government data; see DATA_SOURCES.md.</p><p>README_VINTAGE.md gives commands. Raw compressed responses, hashes, availability snapshots, window-level feature/label provenance, masks, models, residual estimates, frozen forecasts and per-sample scores are included. Independent verification checks archive chronology, model reload predictions and pinball-based WIS. Codex implemented, executed, tested and documented this stage; team members should disclose that scope, independently inspect assumptions and provide their own reflections on AI assistance.</p></html>'''
    (out/'vintage_report.html').write_text(body)
